#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <arpa/inet.h>
#include <openssl/sha.h>

static const char *b64t = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static void b64(const uint8_t *in, size_t len, char *out)
{
    size_t i, o = 0;
    for (i = 0; i < len; i += 3) {
        uint32_t v = in[i] << 16;
        if (i + 1 < len) v |= in[i + 1] << 8;
        if (i + 2 < len) v |= in[i + 2];
        out[o++] = b64t[(v >> 18) & 0x3F];
        out[o++] = b64t[(v >> 12) & 0x3F];
        out[o++] = (i + 1 < len) ? b64t[(v >> 6) & 0x3F] : '=';
        out[o++] = (i + 2 < len) ? b64t[v & 0x3F] : '=';
    }
    out[o] = 0;
}

static void v4(uint16_t seed, const char *s, const char *d, uint8_t proto,
               uint16_t sp_h, uint16_t dp_h)
{
    struct {
        uint16_t seed;
        uint32_t src;
        uint32_t dst;
        uint8_t proto;
        uint8_t pad0;
        uint16_t sp;
        uint16_t dp;
    } __attribute__((__packed__)) ipv4;

    uint32_t src, dst;
    inet_pton(AF_INET, s, &src);
    inet_pton(AF_INET, d, &dst);
    uint16_t sp = htons(sp_h), dp = htons(dp_h);

    ipv4.seed = htons(seed);
    if (ntohl(src) < ntohl(dst) || (src == dst && ntohs(sp) < ntohs(dp))) {
        ipv4.src = src; ipv4.dst = dst; ipv4.sp = sp; ipv4.dp = dp;
    } else {
        ipv4.src = dst; ipv4.dst = src; ipv4.sp = dp; ipv4.dp = sp;
    }
    ipv4.proto = proto;
    ipv4.pad0 = 0;

    uint8_t hash[20];
    SHA1((const unsigned char *)&ipv4, sizeof(ipv4), hash);
    char out[64];
    b64(hash, sizeof(hash), out);
